import gzip
import hashlib
import json
from pathlib import Path
import random

import chess

root=Path('/workspace/HarbiChess')
parent=root/'docs/research/UFUK-narrow-self-opening-splits-20261003.json'
book=json.loads(parent.read_text())
seen=set()
native = root/'artifacts/ufuk-balanced-data-20261003'
manifest = json.loads((native/'dataset.json').read_text())
for filename, checksum in manifest['files'].items():
    p = native/filename
    assert hashlib.sha256(p.read_bytes()).hexdigest()==checksum
    d=json.loads(gzip.decompress(p.read_bytes()))
    for row in d['rows']:
        seen.add(' '.join(row['fen'].split()[:4]))
arenas=0
for directory in (root/'artifacts').glob('*arena*'):
    if not directory.is_dir():
        continue
    for p in directory.glob('*.json'):
        d=json.loads(p.read_text())
        if not isinstance(d.get('games'), list):
            continue
        arenas+=1
        for game in d['games']:
            b=chess.Board()
            seen.add(' '.join(b.fen().split()[:4]))
            for uci in game['moves']:
                b.push_uci(uci);seen.add(' '.join(b.fen().split()[:4]))
rng=random.Random(20261016)
rows=[]
for row in book['splits']['arena']:
    for attempt in range(1,1001):
        b=chess.Board();moves=list(row['opening']['moves'])
        for uci in moves:b.push_uci(uci)
        while len(moves)<32 and b.outcome(claim_draw=True) is None:
            m=rng.choice(sorted(b.legal_moves,key=lambda m:m.uci()));b.push(m);moves.append(m.uci())
        key=' '.join(b.fen().split()[:4])
        if len(moves)==32 and b.outcome(claim_draw=True) is None and key not in seen:
            seen.add(key)
            rows.append({'family':row['family'],'prefix4':row['prefix4'],'opening':{'moves':moves,'fen':b.fen(),'name':row['opening']['name']+'; value-calibration legal extension','eco':row['opening']['eco']},'parent_opening':row['opening'],'accepted_attempt':attempt})
            break
    else:raise RuntimeError('no legal unseen root')
result={'schema':1,'seed':20261016,'source':{'parent_path':str(parent.relative_to(root)),'parent_sha256':hashlib.sha256(parent.read_bytes()).hexdigest(),'licence':'CC0 original opening book, uniform legal suffixes'},'selection':'24 fresh32ply roots; same development families; no engine/model filtering; current root excluded from all native labels/prior arena states','prior_arena_files_checked':arenas,'splits':{'arena':rows}}
p=root/'docs/research/UFUK-value-opening-splits-20261003.json';assert not p.exists();p.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'roots':len(rows),'prior_arena_files_checked':arenas}))

